mapper.select:
SELECT
FROM finance_recurring r LEFT JOIN finance_category c ON c.id = r.category_id AND c.deleted = 0 LEFT JOIN finance_account a ON a.id = r.account_id AND a.deleted = 0 LEFT JOIN finance_account fa ON fa.id = r.from_account_id AND fa.deleted = 0 LEFT JOIN finance_account ta ON ta.id = r.to_account_id AND ta.deleted = 0
r.deleted = 0
AND r.name LIKE CONCAT('%', #{dto.name}, '%')
AND r.direction = #{dto.direction}
AND r.cycle = #{dto.cycle}
AND r.enabled = #{dto.enabled}
ORDER BY r.id DESC
